mapper.select:
SELECT s.id, s.user_id, s.student_no as studentNo, u.real_name as realName, u.gender, s.birth_date, s.admission_date as admissionDate, u.phone, u.email, s.address, m.name as majorName, m.code as majorCode, c.name as collegeName, m.grade, m.class_no as classNo, s.status, CASE WHEN s.status = 0 THEN '在读' WHEN s.status = 1 THEN '休学' WHEN s.status = 2 THEN '退学' WHEN s.status = 3 THEN '毕业' ELSE '未知' END as statusText, s.create_time as createTime, s.update_time as updateTime, s.create_by as createBy, s.update_by as updateBy, s.is_deleted as isDeleted FROM students s LEFT JOIN users u ON s.user_id = u.id LEFT JOIN majors m ON s.major_code = m.code AND s.grade = m.grade AND s.class_no = m.class_no LEFT JOIN colleges c ON m.college_id = c.id
s.is_deleted = 0
AND s.student_no LIKE CONCAT('%', #{query.studentNo}, '%')
AND u.real_name LIKE CONCAT('%', #{query.realName}, '%')
AND m.code = #{query.majorCode}
AND m.grade = #{query.grade}
AND m.class_no = #{query.classNo}
AND s.status = #{query.status}
ORDER BY s.create_time DESC, s.student_no ASC

SELECT s.id, s.student_no as studentNo, s.admission_date as admissionDate, m.name as majorName, m.code as majorCode, u.real_name as realName, u.gender, u.email, u.phone, m.grade, m.class_no as classNo, s.status, CASE WHEN s.status = 0 THEN '在读' WHEN s.status = 1 THEN '休学' WHEN s.status = 2 THEN '退学' WHEN s.status = 3 THEN '毕业' ELSE '未知' END as statusText, s.create_time as createTime, s.update_time as updateTime, s.is_deleted as isDeleted FROM students s LEFT JOIN users u ON s.user_id = u.id LEFT JOIN majors m ON s.major_code = m.code AND s.grade = m.grade AND s.class_no = m.class_no
s.is_deleted = 0
AND s.student_no LIKE CONCAT('%', #{studentNo}, '%')
AND u.real_name LIKE CONCAT('%', #{name}, '%')
AND m.code = #{majorCode}
AND m.grade = #{grade}
AND m.class_no = #{classNo}
ORDER BY m.grade DESC, m.class_no ASC, s.student_no ASC LIMIT #{offset}, #{pageSize}

